#[inductive(shared_finish)]
fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    broadcast use vstd::multiset::group_multiset_axioms;
    reveal(Self::filter_r);
    let t = pre.storage->0;

    assert forall |r0: int| 0 <= r0 < post.rc_width implies
        #[trigger] post.ref_counts.index(r0) ==
            post.shared_pending.count(r0) as int +
                Self::filter_r(post.shared_guard, r0).len() as int
    by {
        assert(pre.ref_counts.index(r0) ==
            pre.shared_pending.count(r0) as int +
                Self::filter_r(pre.shared_guard, r0).len() as int);

        if r0 == r {
            // After the transition:
            // post.shared_guard = pre.shared_guard.insert((r, t))
            // post.shared_pending = pre.shared_pending.remove(r)

            // filter_r for r increases by 1
            assert(Self::filter_r(post.shared_guard, r) =~=
                   Self::filter_r(pre.shared_guard, r).insert((r, t))) by {
                assert forall |v: (int, T)|
                    #[trigger] Self::filter_r(post.shared_guard, r).count(v) ==
                    Self::filter_r(pre.shared_guard, r).insert((r, t)).count(v)
                by {
                    // post.shared_guard = pre.shared_guard.insert((r, t))
                    // LHS = if v.0 == r then post.shared_guard.count(v) else 0
                    //      = if v.0 == r then (pre.shared_guard.count(v) + singleton(r,t).count(v)) else 0
                    // RHS = filter_r(pre.shared_guard, r).count(v) + singleton(r,t).count(v)
                    //      = (if v.0 == r then pre.shared_guard.count(v) else 0) + singleton(r,t).count(v)
                    // When v.0 != r: singleton(r,t).count(v) = 0 since (r,t).0 = r != v.0
                };
            };
            assert(Self::filter_r(post.shared_guard, r).len() ==
                   Self::filter_r(pre.shared_guard, r).len() + 1);

            // shared_pending count for r decreases by 1
            assert(post.shared_pending.count(r) ==
                   (pre.shared_pending.count(r) - 1) as nat);
        } else {
            // filter_r for r0 is unchanged
            assert(Self::filter_r(post.shared_guard, r0) =~=
                   Self::filter_r(pre.shared_guard, r0)) by {
                assert forall |v: (int, T)|
                    #[trigger] Self::filter_r(post.shared_guard, r0).count(v) ==
                    Self::filter_r(pre.shared_guard, r0).count(v)
                by {
                    // post.shared_guard = pre.shared_guard.insert((r, t))
                    // If v.0 == r0 != r, then v != (r, t), so singleton count = 0
                    // If v.0 != r0, both sides = 0
                };
            };
            // shared_pending count for r0 is unchanged (only r is removed)
            assert(post.shared_pending.count(r0) == pre.shared_pending.count(r0));
        }
    };
}

